import{_ as t}from"./chunks/35-inpaint-before-after.zzj8j6F4.js";import{_ as o,o as a,c as s,a2 as r}from"./chunks/framework.CXsxtpvq.js";const n="/asset-studio/shots/en/29-gallery-send-to-tools.webp",i="/asset-studio/shots/en/31-tools-analysis.webp",l="/asset-studio/shots/en/36-tools-tags.webp",g="/asset-studio/shots/en/33-tools-inpaint.webp",d="/asset-studio/shots/en/38-tools-alpha-preview.webp",h="/asset-studio/shots/en/39-tools-censor.webp",v=JSON.parse('{"title":"Image tools","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tools.md","filePath":"guide/tools.md"}'),p={name:"guide/tools.md"};function m(c,e,u,w,b,f){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="image-tools" tabindex="-1">Image tools <a class="header-anchor" href="#image-tools" aria-label="Permalink to &quot;Image tools&quot;">​</a></h1><p>The <strong>Image tools</strong> collect the work you do one image at a time. Source images are never changed; results are always saved as new files.</p><h2 id="adding-images" tabindex="-1">Adding images <a class="header-anchor" href="#adding-images" aria-label="Permalink to &quot;Adding images&quot;">​</a></h2><ul><li><strong>Upload files or ZIP</strong>: PNG, WebP or JPEG files, or a ZIP of them. You can also drop them on the page.</li><li><strong>From the gallery</strong>: choose images in the gallery and press <strong>Send to image tools</strong>.</li></ul><p><img src="'+n+'" alt="Sending from the gallery"></p><p>Click an image in the list on the left to see it with how it was made. The Asset Studio record, the ComfyUI graph, A1111 <code>parameters</code> and EXIF are read to show the prompt and settings, and <strong>Open in Lab</strong> hands them to the lab.</p><p><img src="'+i+'" alt="Reading how an image was made"></p><p>Ticked images can be downloaded at once with <strong>Download ZIP</strong>.</p><h2 id="where-results-go" tabindex="-1">Where results go <a class="header-anchor" href="#where-results-go" aria-label="Permalink to &quot;Where results go&quot;">​</a></h2><ul><li>Results of work images (images in a work / character / outfit folder) are saved <strong>next to the source as new candidates</strong>. Inpainting <code>002.png</code>, for example, creates <code>002_inpaint.png</code>; pass it in the gallery to make it the adopted image of that expression.</li><li>Results of uploaded images and lab images go to <code>outputs/_tools/&lt;date&gt;/</code>.</li></ul><h2 id="tagging" tabindex="-1">Tagging <a class="header-anchor" href="#tagging" aria-label="Permalink to &quot;Tagging&quot;">​</a></h2><p>The WD14 tagger reads tags from the image and compares them with the image&#39;s prompt.</p><p><img src="'+l+'" alt="Tagging result"></p><ul><li><strong>Matches the prompt</strong>: in the prompt and seen in the image.</li><li><strong>Only seen in the image</strong>: not in the prompt but visible. Useful for spotting things you did not ask for.</li><li><strong>Not seen in the image</strong>: in the prompt but not read from the image. Either it was not drawn or the tagger does not know the phrase.</li></ul><p><strong>Copy tags</strong> and <strong>Open tags in lab</strong> are available. Tags listed under <strong>Excluded tags</strong> on the right are left out of the view, copies and exports. <strong>Export tags</strong> as TXT packs one caption file per image, named like the image ZIP (for LoRA training).</p><p>Tagging shares the generation queue, so it runs after images being generated.</p><h2 id="inpaint" tabindex="-1">Inpaint <a class="header-anchor" href="#inpaint" aria-label="Permalink to &quot;Inpaint&quot;">​</a></h2><p>Redraws only the painted area with the image&#39;s own model, LoRAs and prompt. Use it to fix part of an image, such as a hand or a prop. It works on images made with Asset Studio (with a record).</p><p><img src="'+g+'" alt="Inpaint mask"></p><ol><li>Paint the <strong>area to redraw</strong> with the green brush and press <strong>Save mask</strong>.</li><li>The <strong>Prompt</strong> starts from the image&#39;s record. Add tags that describe the fix if you like.</li><li>Choose the <strong>Area to redraw</strong>: <ul><li><strong>Mask area, enlarged (recommended)</strong>: crops around the mask, redraws it enlarged to the generation size and pastes it back. Small parts such as fingers come out sharper. A wider <strong>context padding</strong> blends in better.</li><li><strong>Whole image</strong>: redraws at the image&#39;s own size.</li></ul></li><li>Set <strong>Denoise</strong>. Higher changes more; start at 0.5–0.7 for hands and props.</li><li>Press <strong>Inpaint this image</strong>.</li></ol><p>Areas you did not paint keep the original pixels.</p><p><img src="'+t+'" alt="Before and after inpainting"></p><h2 id="background-removal" tabindex="-1">Background removal <a class="header-anchor" href="#background-removal" aria-label="Permalink to &quot;Background removal&quot;">​</a></h2><ol><li><strong>Split the background</strong>: isnet-anime (for anime illustrations) or person segmentation finds the area to keep.</li><li><strong>Fix the mask</strong>: the blue area is kept. Add with the brush, remove with the eraser, then save. <strong>Preview result</strong> shows the cut-out right away.</li><li><strong>Apply</strong>: choose mask growth and edge softness and apply to save a PNG with a transparent background.</li></ol><p><img src="'+d+'" alt="Background removal preview"></p><p>Upscaling drops transparency, so remove the background after upscaling.</p><h2 id="censor" tabindex="-1">Censor <a class="header-anchor" href="#censor" aria-label="Permalink to &quot;Censor&quot;">​</a></h2><ol><li><strong>Detect areas</strong> (optional): finds the areas to cover automatically. It can miss some, so always check.</li><li><strong>Fix the mask</strong>: the red area is covered. You can also paint it without detection.</li><li><strong>Apply</strong>: choose mosaic, blur or a solid colour, with strength, colour, mask growth and edge softness.</li></ol><p><img src="'+h+'" alt="Censor"></p><p>Censor and background removal can be applied to several images at once with the &quot;apply to the chosen images with a mask&quot; button; each image uses its own saved mask.</p><h2 id="the-mask-editor" tabindex="-1">The mask editor <a class="header-anchor" href="#the-mask-editor" aria-label="Permalink to &quot;The mask editor&quot;">​</a></h2><p>Inpaint, background removal and censor share one editor.</p><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td>Brush / eraser</td><td><strong>B</strong> / <strong>E</strong></td></tr><tr><td>Brush size</td><td><strong>[</strong> / <strong>]</strong> or the size slider</td></tr><tr><td>Undo / redo</td><td><strong>Ctrl+Z</strong> / <strong>Ctrl+Y</strong></td></tr><tr><td>Zoom</td><td>Mouse wheel</td></tr><tr><td>Pan</td><td>Drag with <strong>Space</strong> held, or with the middle button</td></tr><tr><td>Fit / 100%</td><td><strong>0</strong> / <strong>1</strong></td></tr></tbody></table><p><strong>Show mask</strong> and its opacity slider hide or fade the mask; <strong>Background</strong> picks what shows behind transparent areas (checker, white or black).</p><h2 id="post-processing" tabindex="-1">Post-processing <a class="header-anchor" href="#post-processing" aria-label="Permalink to &quot;Post-processing&quot;">​</a></h2><ul><li><strong>Upscale</strong>: enlarges with an upscale model and matches the final scale you set.</li><li><strong>Detailer</strong> (experimental): finds faces, eyes, mouths and hands and redraws them with the image&#39;s own model. Faces can change, so check the result.</li></ul><h2 id="webp-conversion" tabindex="-1">WebP conversion <a class="header-anchor" href="#webp-conversion" aria-label="Permalink to &quot;WebP conversion&quot;">​</a></h2><p>Converts to WebP with quality, lossless and long-side options. <strong>Keep metadata</strong> is off by default, so shared files carry no prompt or workflow.</p>',38)])])}const P=o(p,[["render",m]]);export{v as __pageData,P as default};
